package com.transmutehider;

import net.runelite.api.events.GraphicChanged;
import net.runelite.api.gameval.SpotanimID;

import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
        name = "Transmute Hider",
        description = "Hides the Transmute relics visual effects",
        tags = {"transmute", "league", "demonic", "pacts", "visual", "effects"}
)
public class TransmuteHiderPlugin extends Plugin {

    @Subscribe
    public void onGraphicChanged(GraphicChanged graphicChange)
    {
        var actor = graphicChange.getActor();

        for (var spotAnim : actor.getSpotAnims())
        {
            if (spotAnim.getId() == SpotanimID.LEAGUE_6_TRANSMUTATION_UPGRADE ||
                spotAnim.getId() == SpotanimID.LEAGUE_6_TRANSMUTATION_DOWNGRADE)
            {
                actor.removeSpotAnim((int) spotAnim.getHash());
                break;
            }
        }
    }
}

package com.transmutehider;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class TransmuteHiderPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TransmuteHiderPlugin.class);
		RuneLite.main(args);
	}
}
